import {OnlineRoom} from './online.js';
import {needsIntro,introOpen,showIntro} from './onboarding.js';
import {createClock,clockReading,advanceClock,formatClock} from './clock.js';
import {versusCatalog,newVersus,hybridName,legalMoves,legalDrops,promotionChoices,versusMove,versusDrop,inCheck,vCoord} from './versus.js';
import {hasProgress,recordMatch,matchFrames} from './matches.js';
import {studyMarkup,startStudyAnimations,controlStudy,flipStudy} from './study.js';
import {makeCatalog,newGame,DRAFT,draftSteps,draftChoice,deploy,roster,moves,move,describe,coord,sideName} from './engine.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed=()=>crypto.getRandomValues(new Uint32Array(1))[0].toString(36).toUpperCase();
let catalog,game,history=[],selected=null,boardSelected=null,view='home',query='',filter='all',promotedView=false,flipped=false;
const originalPieces={'king':'OU','pawn':'FU','rook':'HI','bishop':'KA','gold-general':'KI','silver-general':'GI','knight':'KE','lance':'KY','dragon-king':'RY','dragon-horse':'UM'};
let piecePageId='king',hoverTimer,hideTimer,hoverAnchor=null;
let matches=[],activeId=crypto.randomUUID(),startedAt=null,matchId='',replayIndex=null,formFilter='base',openTimer;
let libraryMode='draft',factionFilter='all',handSelected=null,pendingMove=null;
let online=null,roomConnecting=false;
let dismissedResult=null,reviewFrame=null,liveForRender=null,soundOn=localStorage.getItem('shogi-sound')!=='off';
let deckIndex=0,deckBusy=false,drag=null;
let pieceDrag=null,suppressBoardClick=0;
const deckIds=['drunken-elephant','heavenly-horse','rook','king'];
const hoverPanel=document.createElement('aside');hoverPanel.className='piece-popover';hoverPanel.hidden=true;hoverPanel.id='piece-preview';hoverPanel.setAttribute('aria-label','棋子动画预览');document.body.append(hoverPanel);
const storageKey='taikyoku-draft-v1';
try{
  const response=await fetch('/data/catalog.json');if(!response.ok)throw Error('棋子资料加载失败');
  catalog={...makeCatalog(await response.json()),...versusCatalog};
  try{const saved=JSON.parse(localStorage.getItem(storageKey));if(saved?.game&&((saved.game.mode==='versus'&&saved.game.board?.length===81)||([1,2].includes(saved.game.version)&&saved.game.board?.length===25&&saved.game.pool.every(id=>catalog[id]?.playable)))){game=saved.game;history=saved.history||[];matches=Array.isArray(saved.matches)?saved.matches:[];activeId=saved.activeId||activeId;startedAt=saved.startedAt??null;}}catch{}
  if(!game)game=newGame(catalog,seed());save();readRoute();render();
}catch(e){app.innerHTML=`<div class="loading">${esc(e.message)}，请刷新页面重试。</div>`;}
function notify(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3000);}
function save(){try{const next=recordMatch(matches,activeId,startedAt,game,history);localStorage.setItem(storageKey,JSON.stringify({game,history,matches:next,activeId,startedAt}));matches=next;return true;}catch{notify('存储空间不足，请先导出棋谱留存。');return false;}}

function commit(next){
 if(online){sendOnline(inferOnlineAction(game,next));return;}
 const before=game,now=Date.now();
 if(before.phase==='play'&&clockReading(before,before.turn,now).expired){finishTimeout();return;}
 const moved=next.ply>before.ply,origins=moved?pieceRects():null;
 advanceClock(before,next,now);pendingMove=null;reviewFrame=null;history.push(structuredClone(before));game=next;handSelected=null;selected=null;boardSelected=null;promotedView=false;save();render();
 if(next.phase==='over'&&before.phase!=='over')revealResult();
 if(before.phase==='placement'&&next.placement>before.placement)playMoveSound(before.mode,before.placement%2,false);
 if(moved){animatePieces(before,next,origins);playMoveSound(before.mode, before.turn, before.board.filter(Boolean).length>next.board.filter(Boolean).length);}
}

function currentSide(){return game.phase==='draft'?draftSteps(game)[game.draft.length].side:game.phase==='placement'?game.placement%2:game.turn;}
function token(id,side=0,promoted=false,small=false){const cp=catalog[id];if(cp?.faction==='chess')return `<span class="chess-piece" style="background-image:url('/vendor/lichess/piece/cburnett/${side===1?'b':'w'}${cp.asset}.svg')" title="${esc(cp.name)}"></span>`;const asset=cp?.faction==='shogi'?cp.asset:originalPieces[id];return `<span class="piece ${side===1?'white':''} ${promoted?'promoted':''} ${small?'small':''} ${[...(catalog[id]?.name||id)].length>2?'long-name':''} ${asset?'original-piece':''}" ${asset?`style="background-image:url('/vendor/lishogi/pieces/0${asset}.svg')"`:''} title="${esc(catalog[id]?.name||id)}"><span>${esc(catalog[id]?.name||id)}</span></span>`;}

function tag(p){return p.rules?.some(r=>r.leap)?'跳跃':p.rules?.some(r=>r.range>1)?'远行':'近战';}
function available(id){return !game.draft.some(d=>d.id===id);}
function header(){return `<header class="header">${brand()}<nav>${[['home','模式'],['library','棋子图鉴'],['history','对战历史']].map(([key,label])=>`<button data-action="${key}" class="${view===key||key==='history'&&view==='match'?'active':''}">${label}</button>`).join('')}<button data-action="rules">玩法规则</button></nav></header>`;}

function team(side){const active=currentSide()===side&&game.phase!=='over';return `<aside class="team ${side?'team-white':''} ${active?'current':''}"><div class="team-title"><span class="side-dot ${side?'light':''}"></span><h2>${sideName(side)}</h2><small>${side?'GOTE':'SENTE'}</small>${active?'<span class="turn-dot"></span>':''}</div><p class="team-sub">${side?'后选应变 · 棋盘上方':'先选落子 · 棋盘下方'}</p><div class="king-row">${token('king',side,false,true)}<span>王将<small>固定王 · 不参与禁选</small></span></div><div class="roster">${Array.from({length:5},(_,i)=>{const id=game.picks[side][i],placed=id&&game.board.some(p=>p?.side===side&&p.base===id);return `<button class="roster-slot ${id?'filled':''} ${selected===id?'chosen':''}" ${id?`data-piece="${id}"`: 'disabled'}><span class="slot-num">0${i+1}</span>${id?`${token(id,side,false,true)}<span>${esc(catalog[id].name)}<small>${game.phase==='placement'?(placed?'已布阵':'待布阵'):tag(catalog[id])}</small></span>`:'<span class="slot-empty">等待选取</span>'}</button>`;}).join('')}</div><div class="ban-title">禁用棋子 <span>${game.bans[side].length} / 5</span></div><div class="bans">${Array.from({length:5},(_,i)=>game.bans[side][i]?`<button title="${esc(catalog[game.bans[side][i]].name)}" data-piece="${game.bans[side][i]}">${esc(catalog[game.bans[side][i]].name)}</button>`:'<span>—</span>').join('')}</div>${game.phase==='placement'?`<button class="button king-deploy" data-piece="king" ${side!==currentSide()?'disabled':''}>${game.board.some(p=>p?.side===side&&p.base==='king')?'王将已布阵':'选择王将布阵'}</button>`:''}</aside>`;}
function detail(){
  const id=selected||game.pool.find(available)||'king';
  const onBoard=boardSelected!==null?game.board[boardSelected]:null;
  const base=onBoard?.promoted&&onBoard.id===id?{...catalog[id],promotion:null}:catalog[id];
  const p=promotedView&&base.promotion?catalog[base.promotion]:base;
  const demo=Array(25).fill(null);demo[12]={id:p.id,side:0};const dest=moves(demo,12,catalog);
  return `<aside class="detail"><div class="eyebrow">PIECE STUDY <span>棋子研习</span></div><div class="detail-piece">${token(p.id,0,promotedView)}<span class="piece-ring"></span></div><h2>${esc(p.name)}</h2><p class="roman">${esc(p.romaji||p.english)}</p><div class="detail-tags"><span>${tag(p)}</span><span>${base.playable?'已实现':base.original?'暂不入池':'升变形态'}</span></div><div class="detail-tabs"><button data-action="base" class="${!promotedView?'active':''}">本体走法</button><button data-action="promotion" ${!base.promotion?'disabled':''} class="${promotedView?'active':''}">升变预览</button></div><div class="movement"><div class="diagram">${demo.map((_,i)=>`<span class="${i===12?'origin':dest.includes(i)?'reachable':''}">${i===12?'駒':dest.includes(i)?'•':''}</span>`).join('')}</div><div class="diagram-legend">↑ 朝向敌方<br><i></i> 可达位置</div></div><p class="move-description">${esc(describe(p))}</p><small class="diagram-note">空棋盘示意；远行受阻挡，跳跃可越子。图外距离见上方说明。</small><div class="promotion-info"><small>首次吃子 · 升变</small><strong>${esc(base.name)} <span>→</span> ${base.promotion?esc(catalog[base.promotion].name):'不升变'}</strong>${base.id==='drunken-elephant'?'<p>太子也是王族，须一并吃掉才能获胜。</p>':''}${base.id==='fire-demon'?'<p>大局将棋的火鬼没有烧杀能力。</p>':''}</div></aside>`;
}
function poolPanel(){return `<section class="pool-panel pick-pool"><div class="pool-grid">${game.pool.map(id=>{const p=catalog[id],taken=game.draft.find(d=>d.id===id);return `<button data-preview="${id}" data-piece="${id}" class="piece-card ${taken?'taken owned-'+taken.side:''}" ${taken?'disabled':''} aria-label="${esc(p.name)}${taken?'，'+sideName(taken.side)+'已选':''}">${token(id)}<strong>${esc(p.name)}</strong><small>${taken?(taken.type==='ban'?'已禁用':sideName(taken.side)+'已选'):p.promotion?'升变 '+esc(catalog[p.promotion].name):'不升变'}</small></button>`;}).join('')}</div></section>`;}
function boardPanel(){
  const placing=game.phase==='placement',side=currentSide(),chosen=placing?(selected&&roster(game,side).includes(selected)&&!game.board.some(p=>p?.side===side&&p.base===selected)?selected:null):null;
  const dest=boardSelected!==null?moves(game.board,boardSelected,catalog):[];
  const indices=Array.from({length:25},(_,i)=>flipped?24-i:i);
  return `<section class="board-panel"><div class="board-top"><span>${placing?'DEPLOYMENT · 布阵':'BATTLE · 对弈'}</span><button class="text-button" data-action="flip">⇄ 翻转棋盘</button></div><div class="board-wrap"><div class="files">${[...(flipped?'EDCBA':'ABCDE')].map(c=>`<span>${c}</span>`).join('')}</div><div class="board">${indices.map(i=>{const p=game.board[i],home=placing&&(side===0?i>=15:i<10)&&!p;return `<button class="square ${boardSelected===i?'selected':''} ${dest.includes(i)?'legal':''} ${home?'home':''} ${game.lastMove?.includes(i)?'last':''}" data-square="${i}" aria-label="${coord(i)}${p?' '+sideName(p.side)+' '+catalog[p.id].name:' 空格'}">${p?token(p.id,p.side,p.promoted):'<span class="move-dot"></span>'}${i%5===0?`<small>${5-Math.floor(i/5)}</small>`:''}</button>`;}).join('')}${resultOverlay()}</div></div><div class="board-caption">${placing?`${sideName(side)}：${chosen?`点击己方高亮空格，放置「${esc(catalog[chosen].name)}」`:'先从阵容中选择一枚棋子，再点击己方两排空格'}<small>双方轮流放置 · ${game.placement} / 12 枚</small>`:game.phase==='over'?`<strong>${game.winner===null?'双方和棋':sideName(game.winner)+'获胜'}</strong><small>这局的选择，成就了这局的故事。</small>`:`${sideName(side)}行棋 · 点击棋子查看可走位置<small>第 ${game.ply+1} 手 · 吃掉全部敌方王族获胜</small>`}</div>${!placing?'<div class="board-actions"><button data-action="draw" class="text-button">协议和棋</button><button data-action="resign" class="text-button">认输</button></div>':''}<div class="game-log"><h3>棋局记录 <span>${game.log.length}</span></h3>${game.log.slice(-7).reverse().map((l,i)=>`<p><small>${String(game.log.length-i).padStart(2,'0')}</small>${esc(l.replace(/\b[a-z]+(?:-[a-z]+)*\b/g,id=>catalog[id]?.name||id))}</p>`).join('')}</div></section>`;
}
function status(){const side=currentSide(),step=draftSteps(game)[game.draft.length];return `<div class="status"><div class="status-icon ${game.phase==='draft'&&step.type==='ban'?'red':''}">${game.phase==='draft'?(step.type==='ban'?'禁':'选'):game.phase==='placement'?'阵':'棋'}</div><div><div class="eyebrow">${game.phase==='draft'?`ROUND 0${step.round} / ${step.type.toUpperCase()} PHASE`:game.phase==='placement'?'PLACE YOUR PIECES':'MAKE YOUR MOVE'}</div><h2>${game.phase==='over'?(game.winner===null?'和棋':sideName(game.winner)+'获胜'):game.phase==='draft'?`${sideName(side)}，${step.type==='ban'?'禁用':'选取'}一枚棋子`:game.phase==='placement'?`${sideName(side)}，请布阵`:`${sideName(side)}，轮到你行棋`}</h2></div><span class="status-count">${game.phase==='draft'?`${String(game.draft.length+1).padStart(2,'0')} <i>/ 20</i>`:game.phase==='placement'?`${game.placement} <i>/ 12</i>`:`${game.ply} <i>手</i>`}</span></div>`;}
function footer(){const step=draftSteps(game)[game.draft.length];return `<footer class="action-bar"><div class="draft-track">${[['ban',1,'第一轮禁用'],['pick',1,'第一轮选取'],['ban',2,'第二轮禁用'],['pick',2,'第二轮选取']].map(([type,round,label])=>`<div class="track-group"><small>${label}</small><div>${DRAFT.map((d,i)=>d.type===type&&d.round===round?`<span title="第${i+1}步 ${sideName(d.side)}${type==='ban'?'禁用':'选取'}" class="track-dot ${d.side?'light':''} ${i<game.draft.length?'done':''} ${i===game.draft.length?'now':''}">${i<game.draft.length?'✓':d.side?'后':'先'}</span>`:'').join('')}</div></div>`).join('')}</div><button class="text-button" data-action="undo" ${!history.length?'disabled':''}>↶ 撤销一步</button>${game.phase==='draft'?`<button class="text-button inspect-button" data-action="inspect" ${!selected?'disabled':''}>查看走法</button><button id="confirm-choice" class="button primary ${step.type==='ban'?'danger':''}" data-action="confirm" ${!selected||!available(selected)||!game.pool.includes(selected)?'disabled':''}>确认${step.type==='ban'?'禁用':'选取'} ${selected&&available(selected)?esc(catalog[selected].name):''} <span>→</span></button>`:`<button class="button primary" data-action="${game.phase==='over'?'new':'export'}">${game.phase==='over'?'再来一局 →':'导出棋谱 ↗'}</button>`}</footer>`;}
function gameInfo(){return `<section class="game-info"><span class="variant-icon">五</span><div><strong>无时限 • 休闲 • 大局将棋</strong><p>☗ 先手 <span>本地玩家</span></p><p>☖ 后手 <span>本地玩家</span></p></div></section><div class="side-nav"><button data-action="game" class="${view==='game'?'active':''}">大局 · 择阵 <b>五</b></button><button data-action="library" class="${view==='library'?'active':''}">棋子图鉴 <b>駒</b></button><button data-action="rules">玩法与来源 <b>本</b></button></div><div class="session-info">5 × 5 棋盘 · 每方六枚<br>种子 ${esc(game.seed)}<br><span class="saved-dot">●</span> 棋局已在此浏览器自动保存</div>`;}
function player(side){return `<div class="ruser ${currentSide()===side&&game.phase!=='over'?'on-turn':''}"><span>●</span><strong>${sideName(side)}</strong><small>${currentSide()===side&&game.phase!=='over'?'轮到你':'本地玩家'}</small></div>`;}
function movesPanel(){return `<section class="round-table"><div class="clock">∞ <small>无时限</small></div>${player(1)}<div class="replay-controls"><button data-action="flip" title="翻转棋盘">⇄</button><button data-action="undo" title="撤销一步" ${history.length?'':'disabled'}>↶</button><button data-action="export" title="导出棋谱">⇩</button><button data-action="rules" title="规则">☰</button></div><div class="rmoves"><div class="areplay"><div class="moves">${game.log.map((l,i)=>`<index>${i+1}</index><move class="${i===game.log.length-1?'active':''}">${esc(l.replace(/\b[a-z]+(?:-[a-z]+)*\b/g,id=>catalog[id]?.name||id))}</move>`).join('')||'<p class="empty">棋局记录将在这里显示</p>'}</div></div></div><div class="rcontrols">${status()}${game.phase==='play'?'<button data-action="draw" title="协议和棋">½ 和棋</button><button data-action="resign" title="认输">⚑ 认输</button>':''}</div>${player(0)}<div class="clock ${currentSide()===0?'running':''}">∞ <small>无时限</small></div></section>`;}
function render(){
 if(pieceDrag){suppressBoardClick=performance.now()+500;clearPieceDrag();}
 document.documentElement.classList.toggle('flipped',view==='game'&&flipped);
 app.getAnimations({subtree:true}).forEach(a=>a.cancel());
 hidePreview();
 if(['home','piece','library','history','match'].includes(view)){app.innerHTML=header()+({home:homePage,piece:piecePage,library:libraryPage,history:historyPage,match:matchPage}[view])();startStudyAnimations(app,catalog);return;}
 document.documentElement.classList.toggle('flipped',flipped);
 liveForRender=game;
 if(reviewFrame!==null)game=history[reviewFrame]||game;
 try{app.innerHTML=game.mode==='versus'?versusPage():draftGamePage();}finally{game=liveForRender;liveForRender=null;}
 const picks=document.querySelector('.pick-sequence'),bead=picks?.querySelector('.current');if(bead)picks.scrollLeft=bead.offsetLeft-picks.offsetLeft-picks.clientWidth/2+bead.clientWidth/2;
 const strip=document.querySelector('.move-timeline'),item=strip?.querySelector('.current');if(item)strip.scrollLeft=item.offsetLeft-strip.offsetLeft-strip.clientWidth/2+item.clientWidth/2;
 positionPromotion();
 if(modal.open&&modal.querySelector('.detail'))modal.innerHTML=`<div class="modal-head"><span>棋子研习</span><button data-action="close" aria-label="关闭">×</button></div>${detail()}`;
 const replay=document.querySelector('.areplay');if(replay)replay.scrollTop=replay.scrollHeight;
 queueMicrotask(()=>{if(!online&&view==='game'&&!modal.open&&!introOpen()&&(needsIntro(game.mode==='versus'?'versus':'draft')||game.introPaused)&&!(game.mode==='versus'&&game.version<3))openModeIntro();});
}

function dialog(html){modal.classList.remove('setup-modal');modal.innerHTML=html;modal.showModal();}
function rules(){dialog(`<div class="modal-head"><span class="eyebrow">大局 · 择阵</span><button data-action="close" aria-label="关闭">×</button></div><h2>先选阵容，再下棋。</h2><p>两个人在同一台设备上轮流操作。每方一枚王将，加上自己选出的五枚棋子。</p><ol><li><strong>抽棋池：</strong>随机抽取 16 种棋子。相同种子，可以再战同一组棋池。</li><li><strong>选阵：</strong>短按棋子直接选取，按住查看走法，红蓝两方各选五枚。顺序为先、后、后、先、先、后、后、先、先、后，不禁用棋子。</li><li><strong>布阵：</strong>双方轮流把棋子放到己方两排的空格。十二枚棋子就位后，先手开始行棋。</li><li><strong>走棋：</strong>点击自己的棋子，再点击标出的合法落点。远行棋子遇子停止，跳跃棋子可以越子。被吃掉的棋子退出本局。</li><li><strong>升变：</strong>有升变形态的棋子，首次吃子时自动翻面，每枚最多一次。图鉴可以预览升变前后的走法。</li><li><strong>获胜：</strong>吃掉对方全部王将与太子即胜。王可以走进受攻击的位置；没有合法走法的一方判负，也可以认输或双方同意和棋。</li></ol><p>每一步自动保存。对战历史可以回看禁选、布阵和行棋过程，也可以导出棋谱。</p><a href="/SOURCES.md" target="_blank">开源与资料来源</a>`);}
app.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;query=e.target.value;render();const input=document.querySelector('#search');input.focus();try{input.setSelectionRange(pos,pos);}catch{}}});
function handle(e){
 const modeEntry=e.target.closest('[data-mode-entry]');if(modeEntry&&!e.target.closest('button,a')){showSetup(modeEntry.dataset.modeEntry);return;}
 const session=e.target.closest('[data-session]');if(session){modal.querySelectorAll('[data-session]').forEach(b=>b.classList.toggle('active',b===session));modal.classList.toggle('online-setup',session.dataset.session==='online');return;}
 const net=e.target.closest('[data-online]');if(net){handleOnline(net.dataset.online);return;}
 if(online&&view==='game'&&e.target.closest('[data-square],[data-vsquare],[data-hand],[data-piece],[data-vpromotion]')&&!onlinePlayable())return;
 if(e.target.closest('[data-dismiss-result]')){dismissedResult=resultKey();render();return;}
 const lesson=e.target.closest('[data-intro-mode]');if(lesson){if(modal.open)modal.close();openModeIntro(lesson.dataset.introMode);return;}
 const jump=e.target.closest('[data-jump]');if(jump){browseMove(Number(jump.dataset.jump));return;}
 const setupSide=e.target.closest('[data-setup-side]');if(setupSide){launchSetup(setupSide.dataset.setupSide);return;}
 const timing=e.target.closest('[data-timing]');if(timing){modal.querySelectorAll('[data-timing]').forEach(b=>b.classList.toggle('active',b===timing));modal.querySelector('.time-sliders').hidden=timing.dataset.timing==='none';return;}
 if(reviewFrame!==null&&e.target.closest('[data-square],[data-vsquare],[data-hand],[data-piece],[data-vpromotion],[data-action=undo],[data-action=draw],[data-action=resign]'))return;

  if(e.type==='click'&&e.detail!==0&&performance.now()<suppressBoardClick&&e.target.closest('[data-vsquare],[data-square],[data-hand],[data-deploy-side]'))return;
  if(e.target.closest('[data-cancel-promotion]')){pendingMove=null;render();return;}
  if(controlStudy(e))return;
  const cardFlip=e.target.closest('[data-card-flip]');if(cardFlip){flipCatalogCard(cardFlip.closest('.catalog-card'));return;}
  const cardOpen=e.target.closest('[data-catalog-open]');if(cardOpen){navigate(`piece/${cardOpen.dataset.detail}`);return;}
  const form=e.target.closest('[data-form]');if(form){changeForm(form.dataset.form);return;}
  const mode=e.target.closest('[data-library-mode]'),faction=e.target.closest('[data-faction]');if(mode){libraryMode=mode.dataset.libraryMode;factionFilter='all';formFilter='base';query='';render();return;}if(faction){factionFilter=faction.dataset.faction;render();return;}
  const entry=e.target.closest('[data-detail]');if(entry){navigate(`piece/${entry.dataset.detail}`);return;}
  const p=e.target.closest('[data-piece]'),square=e.target.closest('[data-square]'),f=e.target.closest('[data-filter]'),a=e.target.closest('[data-action]');
  try{
    if(p){if(p.dataset.deploySide!==undefined&&Number(p.dataset.deploySide)!==currentSide())return;if(game.phase==='draft'){if(performance.now()<suppressPickClick)return;commit(draftChoice(game,p.dataset.piece));return;}selected=p.dataset.piece;promotedView=false;render();return;}
    const vs=e.target.closest('[data-vsquare]'),hand=e.target.closest('[data-hand]'),promotion=e.target.closest('[data-vpromotion]');
    if(hand){handSelected=hand.dataset.hand;boardSelected=null;render();return;}
    if(promotion&&pendingMove){const [from,to]=pendingMove;pendingMove=null;commit(versusMove(game,from,to,promotion.dataset.vpromotion||null));return;}
    if(pendingMove&&e.target.closest('[data-action]')){pendingMove=null;render();}
    if(vs){handleVersusSquare(Number(vs.dataset.vsquare));return;}
    if(f){filter=f.dataset.filter;render();return;}
    if(square){const i=Number(square.dataset.square);if(game.phase==='placement'){if(!selected){notify('先选择王将或阵容中的一枚棋子');return;}commit(deploy(game,selected,i));return;}if(game.phase!=='play')return;
      if(boardSelected!==null&&moves(game.board,boardSelected,catalog).includes(i)){commit(move(game,boardSelected,i,catalog));return;}
      const q=game.board[i];boardSelected=q?.side===game.turn?i:null;if(q)selected=q.id;promotedView=false;render();return;}
    if(!a)return;
    switch(a.dataset.action){
      case 'home':modal.close();navigate('home');break;
      case 'contact':contactAuthor();break;
      case 'copy-wechat':navigator.clipboard.writeText('a1225249410').then(()=>notify('微信号已复制'),()=>notify('微信号：a1225249410'));break;
      case 'versus-new':showSetup('versus');break;
      case 'tutorial':openModeIntro();break;
      case 'settings':dialog('<h2>对局设置</h2><button data-action="sound">'+(soundOn?'关闭音效':'开启音效')+'</button><button data-action="close">完成</button>');break;
      case 'sound':soundOn=!soundOn;localStorage.setItem('shogi-sound',soundOn?'on':'off');modal.close();render();break;
      case 'game':navigate(game.onlineRoomId?'room/'+game.onlineRoomId:'game');break;
      case 'library':navigate('library');break;
      case 'history':navigate('history');break;
      case 'deck-next':swipeDeck(1);break;
      case 'deck-prev':swipeDeck(-1);break;
      case 'replay-prev':stepReplay(-1);break;
      case 'replay-next':stepReplay(1);break;
      case 'export-match':exportMatch();break;
      case 'resume-match':{if(matchId.startsWith('online-')){navigate('room/'+matchId.slice(7));break;}const m=matches.find(m=>m.id===matchId);if(m&&m.game.phase!=='over'&&save()){online?.stop();online=null;game=structuredClone(m.game);history=structuredClone(m.history);activeId=m.id;startedAt=m.startedAt;save();navigate('game');}break;}
      case 'rules':rulesMenu();break;
      case 'inspect':dialog(`<div class="modal-head"><span>棋子研习</span><button data-action="close" aria-label="关闭">×</button></div>${detail()}`);break;
      case 'close':modal.close();break;
      case 'base':promotedView=false;render();break;
      case 'promotion':promotedView=true;render();break;
      case 'flip':flipped=!flipped;render();break;
      case 'confirm':if(selected){modal.close();commit(draftChoice(game,selected));}break;
      case 'undo':if(online){sendOnline({type:'offer-undo'});break;}if(history.length){game=history.pop();if(game.clock)game.clock.since=game.phase==='play'?Date.now():null;selected=null;boardSelected=null;save();render();}break;
      case 'new':showSetup('draft');break;
      case 'start':launchSetup('first');break;
      case 'export':{const blob=new Blob([JSON.stringify({format:'taikyoku-draft-v1',rules:'capture-promote-once',game,history},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`taikyoku-${game.seed.replace(/[^a-z0-9-]/gi,'_')}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}
      case 'draw':case 'resign':if(online){if(a.dataset.action==='draw')sendOnline({type:'offer-draw'});else dialog('<h2>确认认输？</h2><p>认输后本局结束。</p><button class="button primary" data-online="resign">确认认输</button><button data-action="close">取消</button>');break;}if(game.phase==='play')dialog(`<div class="modal-head"><span class="eyebrow">END GAME</span><button data-action="close" aria-label="关闭">×</button></div><h2>${a.dataset.action==='draw'?'双方同意和棋？':(game.mode==='versus'?hybridName(game.turn):sideName(game.turn))+'确认认输？'}</h2><p>${a.dataset.action==='draw'?'请两位玩家共同确认。':'本局将由对方获胜。'}</p><button class="button primary" data-action="${a.dataset.action==='draw'?'end-draw':'end-resign'}">确认结束本局</button>`);break;
      case 'end-draw':case 'end-resign':{if(game.phase!=='play')break;const next=structuredClone(game);next.phase='over';next.winner=a.dataset.action==='end-draw'?null:1-game.turn;next.log.push(next.winner===null?'双方协议和棋':(game.mode==='versus'?hybridName(game.turn):sideName(game.turn))+'认输');modal.close();commit(next);break;}
    }
  }catch(err){notify(err.message);}
}
app.addEventListener('click',handle);modal.addEventListener('click',handle);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){hidePreview();clearTimeout(openTimer);}if(e.key==='Enter'&&view==='game'&&!modal.open&&e.target===document.body)document.querySelector('#confirm-choice:not(:disabled)')?.click();});

function readRoute(){
 if(location.hash==='#game'&&game?.onlineRoomId&&!online){window.history.replaceState(null,'','#room/'+game.onlineRoomId);}
 const roomRoute=location.hash.match(/^#room\/([a-f0-9]{16})$/);if(roomRoute){view='game';if(online?.id!==roomRoute[1]){view='home';queueMicrotask(()=>connectRoom(roomRoute[1]));}return;}
 pendingMove=null;reviewFrame=null;
 clearTimeout(openTimer);const route=location.hash.slice(1)||'home';
 if(route.startsWith('piece/')){piecePageId=route.slice(6);view='piece';}
 else if(route.startsWith('match/')){matchId=route.slice(6);replayIndex=null;view='match';}
 else view=['home','game','library','history'].includes(route)?route:'home';
}
function navigate(route){if(location.hash==='#'+route){readRoute();render();}else location.hash=route;}
window.addEventListener('hashchange',()=>{readRoute();boardSelected=null;render();window.scrollTo(0,0);});
function homePage(){return `<main class="home-page lab-home mode-home"><section class="mode-intro"><h1>棋逢对手？<br><em>不如棋逢异类。</em></h1><p>抢一手怪招，掀一盘好戏。</p></section><section class="mode-grid"><article class="mode-card" data-mode-entry="draft" tabindex="0" aria-label="设置 BP 大将棋对局">${modeCover('draft')}<div class="mode-copy"><small>01 / 选阵对弈</small><h2>BP 大将棋</h2><p>从十六枚异兽里，抢出你的五员奇兵。<br>五乘五的小战场，装不下套路。</p><button class="cover-guide" data-intro-mode="draft">玩法演示 ↗</button><button class="mode-start" data-action="new">开始选阵 <span>→</span></button>${game.mode!=='versus'&&hasProgress(game)&&game.phase!=='over'?'<button class="continue-game" data-action="game">继续当前对局</button>':''}</div></article><article class="mode-card" data-mode-entry="versus" tabindex="0" aria-label="设置 Chess vs Shogi 对局">${modeCover('versus')}<div class="mode-copy"><small>02 / 异种对弈</small><h2>Chess vs Shogi</h2><p>你有双王，我有援军。<br>被吃掉的棋子，下一手可能倒戈。</p><button class="cover-guide" data-intro-mode="versus">玩法演示 ↗</button><button class="mode-start" data-action="versus-new">开始对弈 <span>→</span></button>${game.mode==='versus'&&game.phase!=='over'?'<button class="continue-game" data-action="game">继续当前对局</button>':''}</div></article></section><section class="home-discover"><div><span class="story-number">走法之间</span><h2>认识一枚棋子</h2><p>向左或向右滑动，看看另一种可能。</p><a href="#library">进入棋子图鉴 →</a></div><section class="home-showcase deck-showcase"><div class="deck-stack" id="piece-deck" tabindex="0" aria-label="棋子卡组，左右方向键切换">${deckCard()}</div><div class="deck-nav"><button data-action="deck-prev" aria-label="上一枚棋子">←</button><span id="deck-count" aria-live="polite">${deckIndex+1} / ${getDeck().length}</span><button data-action="deck-next" aria-label="下一枚棋子">→</button></div></section></section><section class="lab-story"><div><span class="story-number">从一盘棋开始</span><h2>我和将棋的故事</h2></div><div class="story-copy"><p>我从小学习围棋，高中迷上国际象棋，连碎片时间也用来下棋。后来接触到将棋，棋子可以升变、被吃掉后还能重返战场——同样是一张棋盘，换一套规则，体验就变了。</p><p>真正让我想自己做游戏的，是大局将棋：庞大的棋盘上，数百枚棋子有着各不相同的走法与升变。我想，如果把这些棋子放进一个小棋盘，让双方开局先抽取棋池、轮流禁选，会怎样？于是有了最初的 BP 将棋原型。</p><p>我也曾在将棋变体社区里玩上整晚，后来做了「将棋对战国际象棋」。Shogi Lab 延续的就是这份好奇：规则还可以怎么改？接下来，这里会继续长出新的实验。</p><span class="story-signature">刘行 · Shogi Lab</span></div></section>${siteFooter()}</main>`;}

function piecePage(){
 const p=catalog[piecePageId];
 if(!p)return `<main class="piece-page"><h1>没有找到这枚棋子</h1><a href="#library">返回图鉴</a></main>`;
 const before=Object.values(catalog).filter(q=>q.promotion===p.id);
 return `<main class="piece-page"><div class="piece-breadcrumb"><a href="#home">首页</a> / <a href="#library">棋子图鉴</a> / ${esc(p.name)}</div><div class="piece-page-grid"><section class="piece-biography"><div class="large-token">${token(p.id)}</div><div class="eyebrow">PIECE ENCYCLOPEDIA</div><h1>${esc(p.name)}</h1><p class="piece-english">${esc(p.english)}<br>${esc(p.romaji)}</p><div class="piece-badges"><span>${p.mode==='versus'?'Chess vs Shogi · '+(p.faction==='chess'?'国际象棋':'标准将棋'):'BP 大将棋 · 大局将棋'}</span></div><p class="variant-note">${variantNote(p)}</p><dl><dt>走法说明</dt><dd>${esc(pieceDescription(p))}</dd><dt>升变规则</dt><dd>${promotionNote(p)}</dd>${before.length?`<dt>由这些棋子升变而来</dt><dd>${before.map(q=>`<a href="#piece/${q.id}">${esc(q.name)}</a>`).join('、')}</dd>`:''}<dt>记谱</dt><dd class="notation">${esc(p.notation||'特殊走法')}</dd></dl><button data-action="library">← 返回棋子图鉴</button></section><section class="piece-demonstration">${studyMarkup(p.id,catalog,token,esc)}<p class="detail-scope">演示为局部空盘示意。完整棋盘和特殊规则以所属模式为准。</p></section></div></main>`;
}
function hidePreview(){clearTimeout(hoverTimer);clearTimeout(hideTimer);hoverPanel.getAnimations({subtree:true}).forEach(a=>a.cancel());hoverPanel.hidden=true;hoverPanel.innerHTML='';hoverAnchor?.removeAttribute('aria-describedby');hoverAnchor=null;}
function showPreview(anchor){
 if(!anchor.isConnected||modal.open)return;
 hidePreview();hoverPanel.classList.toggle('passive',view==='game');hoverAnchor=anchor;anchor.setAttribute('aria-describedby','piece-preview');
 hoverPanel.innerHTML=studyMarkup(anchor.dataset.preview,catalog,token,esc,true);hoverPanel.hidden=false;
 const r=anchor.getBoundingClientRect(),w=hoverPanel.offsetWidth,h=hoverPanel.offsetHeight;
 let left=r.right+12;if(left+w>innerWidth-12)left=r.left-w-12;
 hoverPanel.style.left=Math.max(12,Math.min(left,innerWidth-w-12))+'px';
 hoverPanel.style.top=Math.max(12,Math.min(r.top,innerHeight-h-12))+'px';
 startStudyAnimations(hoverPanel,catalog);
}
function queuePreview(e){if(view==='game')return;const anchor=e.target.closest('[data-preview]');if(!anchor||anchor.disabled||anchor.contains(e.relatedTarget))return;if(e.type==='pointerover'&&e.pointerType==='touch')return;clearTimeout(hideTimer);clearTimeout(hoverTimer);hoverTimer=setTimeout(()=>showPreview(anchor),e.type==='focusin'?0:220);}
app.addEventListener('pointerover',queuePreview);app.addEventListener('focusin',queuePreview);
function leavePreview(e){const anchor=e.target.closest('[data-preview]');if(!anchor||anchor.contains(e.relatedTarget)||hoverPanel.contains(e.relatedTarget))return;clearTimeout(hoverTimer);hideTimer=setTimeout(hidePreview,160);}
app.addEventListener('pointerout',leavePreview);app.addEventListener('focusout',leavePreview);
hoverPanel.addEventListener('pointerenter',()=>clearTimeout(hideTimer));hoverPanel.addEventListener('pointerleave',()=>{hideTimer=setTimeout(hidePreview,160);});hoverPanel.addEventListener('focusin',()=>clearTimeout(hideTimer));hoverPanel.addEventListener('focusout',e=>{if(!hoverPanel.contains(e.relatedTarget))hideTimer=setTimeout(hidePreview,160);});
hoverPanel.addEventListener('click',controlStudy);
window.addEventListener('scroll',e=>{if(!hoverPanel.contains(e.target))hidePreview();},true);window.addEventListener('resize',hidePreview);

function getDeck(){return [...new Set([...deckIds,...Object.values(catalog).filter(p=>p.original&&p.rules&&!p.mode).map(p=>p.id)])].filter(id=>catalog[id]);}
function deckCard(){return `<div class="deck-card">${studyMarkup(getDeck()[deckIndex],catalog,token,esc,true)}</div>`;}
async function swipeDeck(direction){
 if(deckBusy||view!=='home')return;deckBusy=true;hidePreview();
 const deck=document.querySelector('#piece-deck'),card=deck.querySelector('.deck-card');
 try{
  if(!matchMedia('(prefers-reduced-motion: reduce)').matches)await card.animate([{transform:card.style.transform||'none',opacity:1},{transform:`translateX(${direction*110}%) rotate(${direction*12}deg)`,opacity:0}],{duration:220,easing:'ease-in',fill:'forwards'}).finished;
  if(!deck.isConnected)return;
  card.getAnimations({subtree:true}).forEach(a=>a.cancel());
  deckIndex=(deckIndex+direction+getDeck().length)%getDeck().length;deck.innerHTML=deckCard();startStudyAnimations(deck,catalog);
  document.querySelector('#deck-count').textContent=`${deckIndex+1} / ${getDeck().length}`;
  if(!matchMedia('(prefers-reduced-motion: reduce)').matches)deck.firstElementChild.animate([{transform:'scale(.96)',opacity:.4},{transform:'scale(1)',opacity:1}],{duration:180,easing:'ease-out'});
 }catch{}finally{deckBusy=false;}
}
app.addEventListener('pointerdown',e=>{const deck=e.target.closest('#piece-deck');if(!deck||e.target.closest('button,a')||deckBusy||e.button!==0)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,dx:0,deck};});
app.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dy)>Math.abs(dx)&&Math.abs(dy)>14){resetDrag();return;}drag.dx=dx;if(Math.abs(dx)>8){drag.deck.setPointerCapture(e.pointerId);drag.deck.querySelector('.deck-card').style.transform=`translateX(${dx}px) rotate(${dx/24}deg)`;}});
function resetDrag(){if(drag?.deck.isConnected){drag.deck.querySelector('.deck-card').style.transform='';if(drag.deck.hasPointerCapture(drag.id))drag.deck.releasePointerCapture(drag.id);}drag=null;}
app.addEventListener('pointerup',e=>{if(!drag||e.pointerId!==drag.id)return;const dx=drag.dx;resetDrag();if(Math.abs(dx)>65)swipeDeck(dx>0?1:-1);});
app.addEventListener('pointercancel',resetDrag);
app.addEventListener('keydown',e=>{if(e.target.closest('#piece-deck')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();swipeDeck(e.key==='ArrowRight'?1:-1);}});

function libraryPage(){return `<main class="catalog-page">${libraryPanel()}${siteFooter()}</main>`;}
function libraryEntries(){return Object.values(catalog).filter(p=>p.original&&(libraryMode==='versus'?p.mode==='versus'&&(factionFilter==='all'||p.faction===factionFilter):!p.mode)).map(p=>({base:p.id,id:formFilter==='promoted'&&p.promotion?p.promotion:p.id})).filter(({base,id})=>!query||[catalog[id].name,catalog[id].english,catalog[base].name].some(v=>(v||'').toLowerCase().includes(query.toLowerCase())));}
function libraryPanel(){const entries=libraryEntries();return `<section class="pool-panel"><div class="panel-heading"><div><h1>棋子图鉴</h1><p>悬停看走法 · 点击棋子看详情 · 按钮翻面</p></div></div><div class="library-modes filters">${[['draft','BP 大将棋'],['versus','Chess vs Shogi']].map(([key,label])=>`<button data-library-mode="${key}" class="${key===libraryMode?'active':''}">${label}</button>`).join('')}</div>${libraryMode==='versus'?`<div class="faction-filters filters">${[['all','双方'],['shogi','将棋方'],['chess','国象方']].map(([key,label])=>`<button data-faction="${key}" class="${key===factionFilter?'active':''}">${label}</button>`).join('')}</div>`:''}<div class="pool-toolbar"><div class="filters">${[['base','升变前'],['promoted','升变后']].map(([k,label])=>`<button data-form="${k}" aria-pressed="${formFilter===k}" class="${formFilter===k?'active':''}">${label}</button>`).join('')}</div><label class="search"><span>⌕</span><input id="search" type="search" placeholder="搜索棋子" value="${esc(query)}" aria-label="搜索棋子"></label></div><div class="catalog-grid">${entries.map(({base,id})=>{const b=catalog[base],back=id!==base;return `<article class="catalog-card ${back?'is-promoted':''}" data-base="${base}" data-back="${back}"><button class="catalog-piece" data-preview="${id}" data-catalog-open data-detail="${id}" aria-label="查看${esc(catalog[id].name)}详情"><span class="catalog-flipper"><span class="catalog-face">${token(base)}</span><span class="catalog-face catalog-back">${token(b.promotion||base,0,!!b.promotion)}</span></span><strong class="catalog-name">${esc(catalog[id].name)}</strong><span class="catalog-relation">${back?'由 '+esc(b.name)+' 升变':b.promotion?'升变为 '+esc(catalog[b.promotion].name):'不升变'}</span></button>${b.promotion?`<div class="catalog-card-actions"><button class="flip-pill" data-card-flip aria-label="翻面查看${esc(b.name)}">翻面</button></div>`:''}</article>`;}).join('')||'<p class="empty">没有找到这枚棋子</p>'}</div></section>`;}
function flipCatalogCard(card){hidePreview();const base=catalog[card.dataset.base];if(!base.promotion)return;setCardSide(card,card.dataset.back!=='true');}
function setCardSide(card,back){const base=catalog[card.dataset.base],id=back&&base.promotion?base.promotion:base.id;card.dataset.back=String(back&&!!base.promotion);card.classList.toggle('is-promoted',back&&!!base.promotion);const button=card.querySelector('.catalog-piece');button.dataset.detail=id;button.dataset.preview=id;button.setAttribute('aria-label',`查看${catalog[id].name}详情`);card.querySelector('.catalog-name').textContent=catalog[id].name;card.querySelector('.catalog-relation').textContent=id!==base.id?'由 '+base.name+' 升变':base.promotion?'升变为 '+catalog[base.promotion].name:'不升变';}
function changeForm(next){if(next===formFilter)return;formFilter=next;hidePreview();document.querySelectorAll('[data-form]').forEach(b=>{b.classList.toggle('active',b.dataset.form===next);b.setAttribute('aria-pressed',String(b.dataset.form===next));});document.querySelectorAll('.catalog-card').forEach(card=>setCardSide(card,next==='promoted'));}

function resultText(g){return g.phase==='over'?(g.winner===null?'和棋':(g.mode==='versus'?hybridName(g.winner):sideName(g.winner))+'获胜'):({draft:'选阵中',placement:'布阵中',play:'未结束'}[g.phase]);}
function dateText(value){return value?new Date(value).toLocaleString('zh-CN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'早期对局';}
function historyPage(){return `<main class="history-page"><div class="history-heading"><div><h1>对战历史</h1><p>每一局的选择，都留在这里。</p></div><button class="button primary" data-action="new">新对局</button></div><div class="history-list">${matches.map(m=>`<a href="#match/${m.id}" class="history-card"><span class="history-emblem">五</span><div><h2>${modeTitle(m.game)} <span>${resultText(m.game)}</span></h2><p>${dateText(m.startedAt)} · ${m.game.ply} 手 · 种子 ${esc(m.game.seed)}</p><small>${m.game.picks.map((ps,i)=>sideName(i)+'：'+(ps.map(id=>catalog[id]?.name||id).join('、')||'尚未选取')).join('<br>')}</small></div><span class="history-open">回看 →</span></a>`).join('')||'<div class="history-empty"><span>棋局从第一手开始</span><p>开始对局后，禁选、布阵和每一步都会留存在这里。</p><button class="button primary" data-action="new">开始第一局</button></div>'}</div><p class="history-storage">历史保存在当前浏览器中，可在回看页导出棋谱。</p></main>`;}
function matchPage(){
 const m=matches.find(m=>m.id===matchId);if(!m)return '<main class="history-page"><h1>未找到这场对局</h1><a href="#history">返回历史</a></main>';
 const frames=matchFrames(m);if(replayIndex===null)replayIndex=frames.length-1;replayIndex=Math.max(0,Math.min(replayIndex,frames.length-1));const g=frames[replayIndex];
 return `<main class="history-page"><a href="#history" class="back-link">← 对战历史</a><div class="history-heading"><div><h1>${modeTitle(m.game)} <small>${resultText(m.game)}</small></h1><p>${dateText(m.startedAt)} · 种子 ${esc(m.game.seed)}</p></div><div>${m.game.phase!=='over'?'<button data-action="resume-match" class="button primary">继续这局</button>':''}<button data-action="export-match" class="button outline">导出棋谱</button></div></div><div class="match-layout"><section><div class="board replay-board ${g.mode==='versus'?'versus-board':''}">${g.board.map((p,i)=>`<div class="square ${g.mode==='versus'&&i<41?'chess-half':''} ${g.lastMove?.includes(i)?'last':''}">${p?token(p.id,p.side,p.promoted):''}</div>`).join('')}</div><div class="replay-slider"><button data-action="replay-prev" ${replayIndex===0?'disabled':''} aria-label="上一步">←</button><input type="range" id="match-scrub" min="0" max="${frames.length-1}" value="${replayIndex}" aria-label="回看进度"><button data-action="replay-next" ${replayIndex===frames.length-1?'disabled':''} aria-label="下一步">→</button></div><p class="replay-caption">${replayIndex} / ${frames.length-1} · ${g.phase==='draft'?'选阵 '+g.draft.length+'/'+draftSteps(g).length:g.phase==='placement'?'布阵 '+g.placement+'/12':resultText(g)+' · '+g.ply+' 手'}</p></section><aside class="replay-summary"><h2>这一刻的阵容</h2>${g.picks.map((ids,i)=>`<h3>${sideName(i)}</h3><p>${ids.map(id=>catalog[id].name).join('、')||'尚未选取'}</p><small>禁用：${g.bans[i].map(id=>catalog[id].name).join('、')||'—'}</small>`).join('')}<h2>棋谱</h2><ol>${g.log.map(l=>`<li>${esc(l.replace(/\b[a-z]+(?:-[a-z]+)*\b/g,id=>catalog[id]?.name||id))}</li>`).join('')}</ol></aside></div></main>`;
}
function stepReplay(delta){const m=matches.find(m=>m.id===matchId);if(!m)return;replayIndex=Math.max(0,Math.min((replayIndex??m.history.length)+delta,m.history.length));render();}
app.addEventListener('input',e=>{if(e.target.id==='match-scrub'){replayIndex=Number(e.target.value);render();document.querySelector('#match-scrub')?.focus();}});
function exportMatch(){const m=matches.find(m=>m.id===matchId);if(!m)return;const url=URL.createObjectURL(new Blob([JSON.stringify(m,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`shogi-lab-${m.id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

function siteFooter(){return '<footer class="lab-footer"><a href="/SOURCES.md" target="_blank">开源协议</a><button data-action="contact">联系作者</button></footer>';}
function contactAuthor(){dialog(`<div class="modal-head"><h2>联系作者</h2><button data-action="close" aria-label="关闭">×</button></div><div class="author-contact"><h3>微信</h3><p>很高兴认识你！</p><p>a1225249410 <button class="flip-pill" data-action="copy-wechat">复制</button></p><div class="wechat-qr"><img src="/assets/author-wechat.jpg" alt="作者微信二维码"></div><small>长按二维码保存，或复制微信号添加</small><a href="https://xing0325.github.io/lixon/#/" target="_blank" rel="noopener">lixon · 我的个人站 ↗</a></div>`);}
function modeTitle(g){return g.mode==='versus'?'Chess vs Shogi':'BP 大将棋';}
function variantNote(p){if(p.mode==='versus')return p.faction==='chess'?'使用国际象棋走法。国象方没有打入；被将棋方吃掉的国象棋子可以由将棋方重新打入。':'使用标准将棋走法。王将八方向一格；进入、离开或在敌阵三排内移动时可以升变。';return ({king:'大局将棋的王将可向八方向走一至两格，不能越子。标准将棋的王将只走一格。','crown-prince':'大局将棋的太子走八方向一格，并可升为王将。标准将棋没有太子。'})[p.id]||'采用大局将棋的走法与升变关系。同名棋子在标准将棋中可能不同；本模式首次吃子升变一次。';}
function pieceDescription(p){return p.id==='c-pawn'?'向前走一格；初始位置未移动时可走两格。斜前方一格吃子，可吃过路兵。':describe(p);}
function promotionNote(p){if(!p.promotion)return '没有升变形态。';if(p.id==='c-pawn')return '到达对侧底线时，选择升为后、车、象或马。图鉴以升后为例。';return p.mode==='versus'?'进入、离开或在敌阵三排内移动时，可选择升变。步、香在底线及桂在末两排必须升变。':`首次吃子时升变为 ${esc(catalog[p.promotion].name)}，每枚棋子仅升变一次。`;}
function brand(){return '<a class="brand org-brand" href="#home" aria-label="Shogi Lab 首页"><img src="/assets/mark.svg" alt=""><span>shogilab<span class="org-suffix">.manus</span></span></a>';}
function zenHeader(){return `<header class="zen-header">${brand()}<span>${modeTitle(game)}</span><button data-action="tutorial">演示</button><button data-action="rules">规则</button></header>`;}
function zenControls(){return `<div class="zen-controls">${[['undo','↶','撤销'],['flip','⇄','翻转棋盘'],['export','⇩','导出'],['settings','⚙','设置'],...(game.phase==='play'?[['draw','½','和棋'],['resign','⚑','认输']]:[])].map(([action,icon,label])=>`<button data-action="${action}" title="${label}" aria-label="${label}" ${action==='sound'?`aria-pressed="${soundOn}"`:''} ${action==='undo'&&(!history.length||game.phase==='over'||reviewFrame!==null)||reviewFrame!==null&&['draw','resign'].includes(action)?'disabled':''}><span aria-hidden="true">${icon}</span><small>${label.replace('关闭音效','音效').replace('开启音效','静音')}</small></button>`).join('')}${game.phase==='over'?`<button data-action="${game.mode==='versus'?'versus-new':'new'}">再来一局</button>`:''}</div>`;}
function draftGamePage(){const draft=game.phase==='draft',placing=game.phase==='placement',side=currentSide();return `${zenHeader()}${onlineBar()}<main class="zen-game ${draft?'zen-draft':''}">${draft?`<div class="pick-heading side-${side}"><span class="player-mark"></span><h1>${sideName(side)}，${draftSteps(game)[game.draft.length].type==='ban'?'禁用':'选取'}一枚棋子</h1><p>${game.version===1?'旧版禁选对局':'点击选取 · 按住查看走法'}</p><span>${game.draft.length+1} / ${draftSteps(game).length}</span></div>${pickSequence()}${poolPanel()}`:`${placing?deploymentTray(flipped?0:1):roundPlayer(flipped?0:1)}${boardPanel()}${placing?deploymentTray(flipped?1:0):roundPlayer(flipped?1:0)+moveTimeline()}${zenControls()}`}</main>`;}
function handStand(){const ids=[...new Set(['c-pawn','c-knight','c-bishop','c-rook','c-queen',...game.hands[0]])];return `<aside class="hand-tray hand-row" aria-label="持驹"><span>持驹</span><div class="hand-pieces">${ids.map(id=>{const count=game.hands[0].filter(p=>p===id).length;return `<button data-hand="${id}" class="hand-stack ${count?'':'empty'} ${handSelected===id?'active':''}" ${!count||game.turn!==0||game.phase!=='play'||pendingMove||reviewFrame!==null?'disabled':''} aria-label="${catalog[id].name}，${count}枚">${token(id)}${count?`<small>${count}</small>`:''}</button>`;}).join('')}</div></aside>`;}
function promotionBar(){if(!pendingMove)return '';const [from,to]=pendingMove;return `<div class="promotion-shade" data-cancel-promotion></div><div class="promotion-bar" role="group" aria-label="选择升变" data-anchor="${to}">${promotionChoices(game,from,to).slice().sort((a,b)=>Number(Boolean(b))-Number(Boolean(a))).map(id=>`<button data-vpromotion="${id||''}" title="${id?'升变为'+catalog[id].name:'不升变'}" aria-label="${id?'升变为'+catalog[id].name:'不升变'}">${token(id||game.board[from].id,game.turn)}</button>`).join('')}</div>`;}
function positionPromotion(){const bar=document.querySelector('.promotion-bar');if(!bar)return;const square=document.querySelector(`[data-vsquare="${bar.dataset.anchor}"]`),shell=document.querySelector('.versus-board-shell'),r=square.getBoundingClientRect(),b=shell.getBoundingClientRect();bar.style.width=r.width+'px';bar.style.setProperty('--choice-height',r.height+'px');bar.style.left=(r.left-b.left)+'px';bar.style.top=Math.max(0,Math.min(r.top-b.top,b.height-bar.offsetHeight))+'px';}
function versusPage(){const dest=pendingMove?[]:handSelected?legalDrops(game,handSelected):boardSelected!==null?legalMoves(game,boardSelected):[],indices=Array.from({length:81},(_,i)=>flipped?80-i:i),check=game.phase==='play'&&inCheck(game,game.turn);return `${zenHeader()}${onlineBar()}<main class="zen-game versus-game"><div class="versus-status"><span class="player-mark side-${game.turn}"></span><h1>${game.phase==='over'?resultText(game):hybridName(game.turn)+'行棋'}</h1><small>${check?'将军':game.ply+' 手'}</small></div>${roundPlayer(flipped?0:1)}${flipped?handStand():''}<div class="versus-arena"><div class="versus-board-shell"><div class="versus-board board ${flipped?'v-flipped':''}">${indices.map(i=>{const p=pendingMove?(i===pendingMove[0]?null:i===pendingMove[1]?game.board[pendingMove[0]]:game.board[i]):game.board[i];return `<button class="square ${i<36?'chess-half':''} ${game.lastMove?.includes(i)?'last':''} ${pendingMove?.[1]===i?'promotion-target':''} ${boardSelected===i?'selected':''} ${dest.includes(i)?'legal':''}" data-vsquare="${i}" aria-label="${vCoord(i)}${p?' '+hybridName(p.side)+' '+catalog[p.id].name:' 空格'}">${p?token(p.id,p.side,p.promoted):'<span class="move-dot"></span>'}</button>`;}).join('')}${resultOverlay()}</div>${promotionBar()}</div></div>${flipped?'':handStand()}${roundPlayer(flipped?1:0)}${moveTimeline()}${zenControls()}</main>`;}
function handleVersusSquare(to){if(game.mode!=='versus'||game.phase!=='play'||pendingMove)return;if(handSelected){if(legalDrops(game,handSelected).includes(to)){commit(versusDrop(game,handSelected,to));return;}handSelected=null;}if(boardSelected!==null&&legalMoves(game,boardSelected).includes(to)){const from=boardSelected,options=promotionChoices(game,from,to);if(options.length>1){pendingMove=[from,to];render();document.querySelector('.promotion-bar button')?.focus({preventScroll:true});}else commit(versusMove(game,from,to,options[0]));return;}boardSelected=game.board[to]?.side===game.turn?to:null;render();}
function versusRules(){dialog(`<div class="modal-head"><h2>Chess vs Shogi</h2><button data-action="close" aria-label="关闭">×</button></div><p>9×9 棋盘，同屏双人，将棋先行。将棋 20 枚按标准阵型摆放，国象九列为车、马、象、王、后、王、象、马、车，前排九个兵。</p><ol><li>双方使用各自棋子的标准走法。新局采用吃王制：将棋王被吃掉即输，国象两个王都被吃掉才输。将军只作提示，可不应将；没有合法走法判负。旧版单王存档仍按将死制。</li><li>只有将棋方可以打入。吃到的国象棋子加入持驹，保留国象走法，朝向随将棋方；升变棋子还原本体。国象方吃掉的棋子退出本局。</li><li>将棋在敌阵三排内可选择升变，无法继续移动的位置强制升变；禁止二步和无路可走的打入。吃王制不适用打步诘；旧版将死制保留打步诘限制。</li><li>国象兵初始可走两格、斜吃、吃过路兵，到底线选择后、车、象或马。王车易位保留。</li><li>本实验不自动处理重复局面、五十步及入玉计分，可双方同意和棋。</li></ol>`);}

window.addEventListener('resize',positionPromotion);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&pendingMove){pendingMove=null;render();}});
app.addEventListener('dragstart',e=>{if(e.target.closest('.board,.komadai,.deployment-tray'))e.preventDefault();});
app.addEventListener('pointerdown',e=>{
 suppressBoardClick=0;
 if(online&&!onlinePlayable())return;
 if(introOpen()||view!=='game'||reviewFrame!==null||pendingMove||modal.open||e.button!==0)return;
 const placement=e.target.closest('[data-deploy-side]'),hand=e.target.closest('[data-hand]'),square=e.target.closest('[data-vsquare],[data-square]');if(!hand&&!square&&!placement)return;
 if(placement&&(game.phase!=='placement'||placement.disabled||Number(placement.dataset.deploySide)!==currentSide()))return;
 const from=square?Number(square.dataset.vsquare??square.dataset.square):null;
 if(hand&&(game.mode!=='versus'||game.turn!==0||hand.disabled))return;
 if(square&&(game.phase!=='play'||game.board[from]?.side!==game.turn))return;
 const source=placement||hand||square,piece=source.querySelector('.piece,.chess-piece');if(!piece)return;
 pieceDrag={id:e.pointerId,x:e.clientX,y:e.clientY,from,deploy:placement?.dataset.piece,hand:hand?.dataset.hand,source,piece,active:false};
});
window.addEventListener('pointermove',e=>{
 const d=pieceDrag;if(!d||d.id!==e.pointerId)return;
 if(!d.active&&Math.hypot(e.clientX-d.x,e.clientY-d.y)<5)return;
 e.preventDefault();
 if(!d.active){d.active=true;hidePreview();d.source.setPointerCapture(e.pointerId);const r=d.piece.getBoundingClientRect();d.ghost=document.createElement('div');d.ghost.className='drag-ghost';d.ghost.innerHTML=d.piece.outerHTML;d.ghost.style.width=r.width+'px';d.ghost.style.height=r.height+'px';const originalStyle=getComputedStyle(d.piece),copy=d.ghost.firstElementChild;copy.style.transform=originalStyle.transform;const originalText=d.piece.querySelector('span'),copyText=copy.querySelector('span');if(originalText&&copyText){const textStyle=getComputedStyle(originalText);for(const key of ['fontSize','lineHeight','fontWeight','letterSpacing'])copyText.style[key]=textStyle[key];}document.body.append(d.ghost);d.source.classList.add('drag-origin');d.targets=d.deploy?game.board.flatMap((p,i)=>!p&&(currentSide()===0?i>=15:i<10)?[i]:[]):d.hand?legalDrops(game,d.hand):game.mode==='versus'?legalMoves(game,d.from):moves(game.board,d.from,catalog);document.querySelectorAll('[data-vsquare],[data-square]').forEach(el=>el.classList.toggle('drag-legal',d.targets.includes(Number(el.dataset.vsquare??el.dataset.square))));}
 d.ghost.style.left=e.clientX+'px';d.ghost.style.top=e.clientY+'px';document.querySelector('.drag-over')?.classList.remove('drag-over');const hit=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-vsquare],[data-square]');if(hit&&d.targets.includes(Number(hit.dataset.vsquare??hit.dataset.square)))hit.classList.add('drag-over');if(d.deploy)previewDeployment(d.deploy,hit?Number(hit.dataset.square):null);
},{passive:false});
function clearPieceDrag(){document.querySelectorAll('.deployment-shadow').forEach(el=>el.remove());const d=pieceDrag;if(!d)return;d.ghost?.remove();d.source.classList.remove('drag-origin');if(d.source.hasPointerCapture(d.id))d.source.releasePointerCapture(d.id);document.querySelectorAll('.drag-legal,.drag-over,.deploy-route').forEach(el=>el.classList.remove('drag-legal','drag-over','deploy-route'));pieceDrag=null;}
window.addEventListener('pointerup',e=>{const d=pieceDrag;if(!d||d.id!==e.pointerId)return;const active=d.active,hit=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-vsquare],[data-square]'),to=hit?Number(hit.dataset.vsquare??hit.dataset.square):null;clearPieceDrag();if(!active)return;suppressBoardClick=performance.now()+500;try{if(to!==null&&d.targets.includes(to)){if(d.deploy){commit(deploy(game,d.deploy,to));}else if(game.mode==='versus'){handSelected=d.hand||null;boardSelected=d.hand?null:d.from;handleVersusSquare(to);}else commit(move(game,d.from,to,catalog));}}catch(err){notify(err.message);}});
window.addEventListener('pointercancel',clearPieceDrag);window.addEventListener('blur',clearPieceDrag);

function roundPlayer(side){const reading=clockReading(game,side,reviewFrame===null?Date.now()+(online?.offset||0):game.clock?.since??Date.now()),active=game.turn===side&&game.phase==='play';return `<div class="round-player ${active?'on-turn':''}"><i class="online-dot"></i><span class="player-name">${esc(online?.state?.players[side]?.name||'Anonymous')}<small>${game.mode==='versus'?hybridName(side):sideName(side)}</small></span><span class="byoyomi">${game.clock?game.clock.byoyomi/1000+'s |':''}</span><time data-clock="${side}" class="round-clock ${reading.period?'in-period':''}">${formatClock(reading.ms)}</time></div>`;}
function moveTimeline(){const live=liveForRender||game,frames=[...history,live],start=frames.findIndex(g=>g.phase==='play'||g.phase==='over');if(start<0)return '';const at=reviewFrame??history.length;return `<div class="round-replay" aria-label="棋谱回放"><button data-jump="${start}" aria-label="回到开局" title="回到开局" ${at<=start?'disabled':''}>⏮</button><button data-jump="${Math.max(start,at-1)}" aria-label="上一步" title="上一步" ${at<=start?'disabled':''}>‹</button><div class="move-timeline">${frames.slice(start).map((g,i)=>{const label=i===0?'开局':g.log.at(-1)?.replace(/^(将棋方|国象方|先手|后手) /,'').replace(/\b[a-z]+(?:-[a-z]+)*\b/g,id=>catalog[id]?.name||id)||'开局';return `<button data-jump="${start+i}" class="${at===start+i?'current':''}" aria-current="${at===start+i?'step':'false'}" title="${esc(label)}"><small>${i||''}</small>${esc(label)}</button>`;}).join('')}</div><button data-jump="${Math.min(history.length,at+1)}" aria-label="下一步" title="下一步" ${at>=history.length?'disabled':''}>›</button><button data-jump="${history.length}" aria-label="回到最新局面" title="回到最新局面" ${at>=history.length?'disabled':''}>⏭</button></div>${reviewFrame!==null?'<button class="return-live" data-jump="'+history.length+'">返回当前对局</button>':''}`;}
function browseMove(index){pendingMove=null;boardSelected=null;handSelected=null;selected=null;reviewFrame=index>=history.length?null:Math.max(0,index);render();}
document.addEventListener('keydown',e=>{if(introOpen()||view!=='game'||modal.open||pendingMove||e.target.closest('input,select,textarea'))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){const start=history.findIndex(g=>g.phase==='play');if(start<0)return;e.preventDefault();browseMove(Math.max(start,Math.min(history.length,(reviewFrame??history.length)+(e.key==='ArrowLeft'?-1:1))));}});
function showSetup(mode){dialog(`<div class="setup-heading">创建对局<button data-action="close" aria-label="关闭">×</button></div><section class="setup-session"><div class="setup-segments"><button data-session="local" class="active">同屏双人</button><button data-session="online">在线邀请</button></div></section><section class="setup-variant"><label for="setup-mode">变体</label><select id="setup-mode"><option value="draft" ${mode==='draft'?'selected':''}>BP 大将棋</option><option value="versus" ${mode==='versus'?'selected':''}>Chess vs Shogi</option></select></section>${roomRows()}<section class="setup-time"><div class="setup-segments"><button data-timing="real" class="active">实时棋局</button><button data-timing="none">无时限</button></div><div class="time-sliders"><label for="setup-minutes">每方分钟数：<strong data-value="setup-minutes">10</strong></label><input id="setup-minutes" type="range" min="1" max="180" value="10"><label for="setup-seconds">读秒秒数：<strong data-value="setup-seconds">10</strong></label><input id="setup-seconds" type="range" min="0" max="60" step="5" value="10"></div></section><section class="setup-players"><p>选择一方</p><div class="setup-sides">${setupSides(mode)}</div><details id="setup-seed-row" ${mode==='versus'?'hidden':''}><summary>棋池种子</summary><input id="new-seed" maxlength="40" value="${seed()}" aria-label="棋池种子"></details></section><footer class="setup-footer">${online?'当前在线房间将保留，可通过邀请链接返回':'选择阵营后开始'}</footer>`);modal.classList.add('setup-modal');modal.classList.remove('online-setup');modal.dataset.onlineSide='first';}
modal.addEventListener('input',e=>{const out=modal.querySelector(`[data-value="${e.target.id}"]`);if(out)out.textContent=e.target.value;});
modal.addEventListener('change',e=>{if(e.target.id==='setup-mode'){modal.querySelector('#setup-seed-row').hidden=e.target.value==='versus';modal.querySelector('.setup-sides').innerHTML=setupSides(e.target.value);}});
function launchSetup(side){if(modal.querySelector('[data-session=online].active')){modal.dataset.onlineSide=side;modal.querySelectorAll('[data-setup-side]').forEach(b=>b.classList.toggle('active',b.dataset.setupSide===side));return;}if(online){online.stop();online=null;}const mode=modal.querySelector('#setup-mode')?.value||'draft',minutes=Number(modal.querySelector('#setup-minutes')?.value||10),seconds=Number(modal.querySelector('#setup-seconds')?.value||0),timed=modal.querySelector('[data-timing].active')?.dataset.timing==='real',gameSeed=modal.querySelector('#new-seed')?.value.trim()||seed();if(!save())return;game=mode==='versus'?newVersus(gameSeed):newGame(catalog,gameSeed);if(timed)game.clock=createClock(minutes,seconds,game.phase==='play');history=[];reviewFrame=null;pendingMove=null;activeId=crypto.randomUUID();startedAt=new Date().toISOString();boardSelected=null;handSelected=null;selected=null;query='';filter='all';flipped=side==='second'||side==='random'&&Math.random()<.5;modal.close();modal.classList.remove('setup-modal');view='game';window.history.replaceState(null,'','#game');save();render();window.scrollTo(0,0);}
function finishTimeout(){if(online)return;if(game.phase!=='play'||!clockReading(game,game.turn).expired)return;const previous=structuredClone(game);advanceClock(previous,game);game.phase='over';game.winner=1-game.turn;game.clock.since=null;game.log.push((game.mode==='versus'?hybridName(game.turn):sideName(game.turn))+'超时');history.push(previous);pendingMove=null;boardSelected=null;handSelected=null;save();render();revealResult();}
setInterval(()=>{if(!game?.clock)return;if(!online&&game.phase==='play'&&clockReading(game,game.turn).expired){finishTimeout();return;}if(view==='game'&&reviewFrame===null)document.querySelectorAll('[data-clock]').forEach(el=>{const r=clockReading(game,Number(el.dataset.clock),Date.now()+(online?.offset||0));el.textContent=formatClock(r.ms);el.classList.toggle('in-period',r.period);});},200);
function pieceRects(){return [...document.querySelectorAll('[data-vsquare],[data-square]')].map(el=>({index:Number(el.dataset.vsquare??el.dataset.square),rect:el.getBoundingClientRect()}));}
function animatePieces(before,after,origins){if(!origins||performance.now()<suppressBoardClick||matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<after.board.length;i++){const p=after.board[i];if(!p||JSON.stringify(before.board[i])===JSON.stringify(p))continue;const from=after.lastMove?.length>1&&i===after.lastMove.at(-1)?after.lastMove[0]:before.board.findIndex((old,j)=>old&&old.side===p.side&&old.id===p.id&&!after.board[j]);const source=origins.find(r=>r.index===from)?.rect,target=document.querySelector(`[data-vsquare="${i}"],[data-square="${i}"]`),piece=target?.querySelector('.piece,.chess-piece');if(!piece)continue;const to=target.getBoundingClientRect();if(source){piece.style.zIndex='5';piece.animate([{translate:`${source.left-to.left}px ${source.top-to.top}px`},{translate:'0 0'}],{duration:180,easing:'cubic-bezier(.25,.8,.25,1)'}).finished.then(()=>piece.style.zIndex='',()=>{});}else piece.animate([{scale:'.8',opacity:.4},{scale:'1',opacity:1}],{duration:140});}}
function playMoveSound(mode,side,capture){
 if(!soundOn)return;
 // Choose by the acting side before the turn changes, including captured chess pieces dropped by shogi.
 const prefix=mode==='versus'&&side===1?'/vendor/lichess/sound/':'/vendor/lishogi/sound/shogi-';
 const audio=new Audio(prefix+(capture?'capture':'move')+'.mp3');audio.volume=.65;audio.play().catch(()=>{});
}

function setupSides(mode){return ['first','random','second'].map((side,i)=>`<button data-setup-side="${side}" aria-label="从${mode==='versus'?['将棋方','随机','国象方'][i]:['先手','随机','后手'][i]}视角开始">${mode==='versus'?`<span class="hybrid-side-icon ${side}">${i!==2?token('s-king'):''}${i!==0?token('c-king',1):''}</span>`:`<span class="side-symbol ${['solid','split','hollow'][i]}"></span>`}<small>${mode==='versus'?['将棋方','随机','国象方'][i]:['先手','随机','后手'][i]}</small></button>`).join('');}
function modeCover(mode){return `<div class="mode-art cinematic-cover ${mode}"><div class="cover-grid"></div><span class="cover-index">${mode==='draft'?'DRAFT / 05':'CROSS / 09'}</span><span class="cover-type">${mode==='draft'?'择阵':'异种'}</span><div class="cover-cast">${mode==='draft'?token('drunken-elephant')+token('rook')+token('heavenly-horse'):token('s-king')+token('c-king',1)}</div><span class="cover-caption">${mode==='draft'?'先抢，再战。':'双王 · 再生'}</span></div>`;}
function openModeIntro(mode=game.mode==='versus'?'versus':'draft'){
 if(introOpen())return;
 const pause=!online&&view==='game'&&game.phase==='play'&&game.clock;
 if(pause){if(clockReading(game,game.turn).expired){finishTimeout();return;}advanceClock(game,game);game.clock.since=null;game.introPaused=true;save();}
 showIntro(mode,()=>{if(pause&&game.phase==='play'){game.clock.since=Date.now();delete game.introPaused;save();}if(view==='game')render();});
}

function deploymentTray(side){const active=currentSide()===side,remaining=roster(game,side).filter(id=>!game.board.some(p=>p?.side===side&&p.base===id));return `<div class="deployment-tray side-${side} ${active?'deploy-current':''}" data-deploy-tray="${side}"><span><i class="player-mark side-${side}"></i>${sideName(side)}<small>${remaining.length?(active?'选择棋子布阵':'等待对方布阵'):'已就位'}</small></span><div class="deployment-pieces">${remaining.map(id=>`<button data-piece="${id}" data-deploy-side="${side}" class="${active&&selected===id?'active':''}" ${active?'':'disabled'} aria-label="${sideName(side)}布阵${catalog[id].name}">${token(id,side,false,true)}</button>`).join('')}</div></div>`;}
function resultKey(){return activeId+':'+game.log.length+':'+game.winner;}
function resultOverlay(){if(game.phase!=='over'||dismissedResult===resultKey())return '';const draw=game.winner===null;return `<div class="board-result ${draw?'is-draw':'winner-'+game.winner}" role="status" aria-live="polite"><div class="result-rays" aria-hidden="true"></div><section class="result-card">${victoryScene()}<span class="result-kicker">对局结束</span><strong>${esc(resultText(game))}</strong><span class="result-rule"></span><p>${draw?'握手，再战。':game.log.at(-1)?.includes('超时')?'对方超时。':game.log.at(-1)?.includes('认输')?'对方认输。':'胜负已定。'}</p><div><button data-dismiss-result>查看棋盘</button><button data-action="${game.mode==='versus'?'versus-new':'new'}">再来一局 →</button></div></section></div>`;}

function revealResult(){document.querySelector('.board-result')?.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}

function rulesMenu(){dialog(`<div class="modal-head"><h2>玩法演示</h2><button data-action="close" aria-label="关闭">×</button></div><div class="rules-menu">${['draft','versus'].map(mode=>`<button data-intro-mode="${mode}">${modeCover(mode)}<strong>${mode==='draft'?'BP 大将棋':'Chess vs Shogi'}</strong><small>${mode==='draft'?'抢棋 · 布阵 · 吃子升变':'双王 · 打入 · 跨棋种对战'}</small><span>播放教程 →</span></button>`).join('')}</div>`);}
function inferOnlineAction(before,next){if(before.phase==='draft')return {type:'pick',piece:next.draft.at(-1).id};if(before.phase==='placement'){const to=next.board.findIndex((p,i)=>p&&!before.board[i]);return {type:'deploy',piece:next.board[to].base,to};}const lm=next.lastMove;if(lm?.length===1)return {type:'drop',piece:next.board[lm[0]].id,to:lm[0]};if(lm?.length===2){const [from,to]=lm;return {type:'move',from,to,promotion:next.board[to].id!==before.board[from].id?next.board[to].id:null};}throw Error('未知在线操作');}
function onlinePlayable(){return online?.connected&&!online.busy&&online.state?.started&&online.state.side===currentSide()&&game.phase!=='over';}
function onlineBar(){if(!online)return '';const s=online.state;return `<aside class="online-bar"><span class="net-status">${online.connected?'● 已连接':'○ 正在重连…'}</span><span>${s?.started?'在线对局':s?.players.every(Boolean)?'等待双方准备':'等待好友加入'}</span><button data-online="copy">复制邀请链接</button><button data-online="leave">离开房间</button>${!s?.started?`<button data-online="ready" ${!online.connected||online.busy||s?.ready[s.side]?'disabled':''}>${s?.ready[s.side]?'你已准备':'准备开始'}</button>`:''}${s?.offer!==null&&s?.offer!==undefined?`<div class="draw-offer">${s.offer===s.side?'已向对方提议和棋':'对方提议和棋 <button data-online="accept-draw">接受</button><button data-online="decline-draw">继续下</button>'}</div>`:''}${s?.undoOffer!=null?`<div class="draw-offer">${s.undoOffer===s.side?'等待对方同意悔棋':'对方申请撤销最近一步 <button data-online="accept-undo">同意</button><button data-online="decline-undo">拒绝</button>'}</div>`:''}</aside>`;}
function updateOnlineStatus(){const bar=document.querySelector('.online-bar');if(bar)bar.outerHTML=onlineBar();}
async function sendOnline(action){try{await online.send(action);}catch(e){notify(e.message);}}
function receiveOnline(data){const before=game,origins=view==='game'?pieceRects():null;game={...data.game,onlineRoomId:data.id};history=data.history;activeId='online-'+data.id;startedAt=data.createdAt;pendingMove=null;boardSelected=null;handSelected=null;selected=null;reviewFrame=null;save();if(view==='game'){render();if(before?.phase==='placement'&&game.placement>before.placement)playMoveSound(before.mode,before.placement%2,false);if(before?.ply<game.ply){animatePieces(before,game,origins);playMoveSound(before.mode,before.turn,before.board.filter(Boolean).length>game.board.filter(Boolean).length);}if(before?.phase!=='over'&&game.phase==='over')revealResult();}}
function attachOnline(data,token){online?.stop();online=new OnlineRoom(data.id,token,receiveOnline,updateOnlineStatus);localStorage.setItem('shogi-seat-'+data.id,token);flipped=data.side===1;view='game';window.history.replaceState(null,'','#room/'+data.id);online.apply(data);online.poll();modal.close();render();}
async function createOnline(side,keepSetup=false){const input={mode:modal.querySelector('#setup-mode').value,minutes:Number(modal.querySelector('#setup-minutes').value),seconds:Number(modal.querySelector('#setup-seconds').value),timed:modal.querySelector('[data-timing=real]').classList.contains('active'),seed:modal.querySelector('#new-seed')?.value,side:side==='second'?1:side==='random'?Math.round(Math.random()):0};if(roomConnecting)return;roomConnecting=true;try{if(!save())return;const data=await OnlineRoom.request('rooms',input);attachOnline(data,data.token);if(keepSetup){dialog('<div class="setup-heading">邀请好友<button data-action="close" aria-label="关闭">×</button></div>'+roomRows()+'<p>房间已创建，等待好友加入。</p><button class="button primary" data-action="close">进入房间</button>');modal.classList.add('online-setup');}}catch(e){notify(e.message);}finally{roomConnecting=false;}}
async function connectRoom(id){if(roomConnecting)return;roomConnecting=true;const token=localStorage.getItem('shogi-seat-'+id);try{if(token){const data=await OnlineRoom.request('rooms/'+id,undefined,token);attachOnline(data,token);}else{dialog(`<div class="modal-head"><h2>加入在线对局</h2><button data-action="close">×</button></div><p>房间 ${esc(id)}</p><label>昵称<input id="online-name" maxlength="24" placeholder="Anonymous"></label><button class="button primary" data-online="join" data-room="${id}">加入对局</button>`);}}catch(e){notify(e.message);dialog('<h2>暂时无法连接房间</h2><p>'+esc(e.message)+'</p><button data-online="retry">重新连接</button><button data-action="home">返回首页</button>');}finally{roomConnecting=false;}}
async function handleOnline(action){try{if(action==='create-room'){await createOnline(modal.dataset.onlineSide||'first',true);}else if(action==='copy-id'){await navigator.clipboard.writeText(online.id);notify('房间号已复制');}else if(action==='copy'){await navigator.clipboard.writeText(location.origin+'/#room/'+online.id);notify('邀请链接已复制');}else if(action==='leave'){online.stop();online=null;modal.close();navigate('home');}else if(action==='join-dialog'){dialog('<h2>加入好友房间</h2><input id="room-address" placeholder="粘贴邀请链接或房间编号"><button class="button primary" data-online="open-room">加入</button><button data-action="close">取消</button>');}else if(action==='open-room'){const value=modal.querySelector('#room-address').value.trim(),id=value.match(/(?:^|room\/)([a-f0-9]{16})$/)?.[1];if(!id)throw Error('请输入有效邀请链接或房间编号');modal.close();navigate('room/'+id);}else if(action==='join'){if(roomConnecting)return;roomConnecting=true;try{const id=modal.querySelector('[data-room]').dataset.room;const data=await OnlineRoom.request('rooms/'+id+'/join',{name:modal.querySelector('#online-name').value});attachOnline(data,data.token);}finally{roomConnecting=false;}}else if(action==='retry'){await connectRoom(location.hash.split('/')[1]);}else{if(action==='resign')modal.close();await sendOnline({type:action});}}catch(e){notify(e.message);}}

function victoryScene(){if(game.winner===null)return '<div class="victory-scene peace"><span>＝</span></div>';const chessWins=game.mode==='versus'&&game.winner===1,winner=chessWins?'c-king':game.mode==='versus'?'s-king':'king',loser=game.mode==='versus'?(chessWins?'s-king':'c-king'):'king';return `<div class="victory-scene" aria-hidden="true"><div class="victory-floor"></div><div class="victory-victim">${token(loser,loser==='c-king'?1:0)}</div>${Array.from({length:6},(_,i)=>`<i class="victory-shard shard-${i}" style="--i:${i}"></i>`).join('')}<div class="victory-stomper">${token(winner,chessWins?1:0)}</div><div class="victory-impact"></div></div>`;}

function pickSequence(){return `<div class="pick-sequence" aria-label="选取顺序">${draftSteps(game).map((d,i)=>`<span class="pick-bead side-${d.side} ${i<game.draft.length?'done':''} ${i===game.draft.length?'current':''}" aria-label="第${i+1}手 ${sideName(d.side)}${i===game.draft.length?' 当前':''}">${i<game.draft.length?'✓':i+1}</span>`).join('')}</div>`;}
function previewDeployment(id,to){document.querySelectorAll('.deployment-shadow').forEach(el=>el.remove());const board=[...game.board];let targets=[];const legal=Number.isInteger(to)&&!board[to]&&(currentSide()===0?to>=15:to<10);if(legal){board[to]={id,side:currentSide()};targets=moves(board,to,catalog);const cell=document.querySelector(`[data-square="${to}"]`);if(cell){const shadow=document.createElement('span');shadow.className='deployment-shadow';shadow.setAttribute('aria-hidden','true');shadow.innerHTML=token(id,currentSide());cell.append(shadow);}}document.querySelectorAll('[data-square]').forEach(el=>el.classList.toggle('deploy-route',targets.includes(Number(el.dataset.square))));}

app.addEventListener('keydown',e=>{const card=e.target.closest('[data-mode-entry]');if(card&&e.target===card&&['Enter',' '].includes(e.key)){e.preventDefault();showSetup(card.dataset.modeEntry);}});

function roomRows(){return `<section class="room-rows"><div class="room-row"><label for="own-room">我的房间</label><input id="own-room" readonly value="${online?.id||''}" placeholder="创建后生成房间号"><button data-online="${online?'copy-id':'create-room'}">${online?'复制房间号':'创建房间'}</button></div><div class="room-row"><label for="room-address">加入房间</label><input id="room-address" placeholder="输入房间号或邀请链接" autocomplete="off"><button data-online="open-room">加入</button></div></section>`;}

let pickHold=null,suppressPickClick=0;
function endPickHold(){if(!pickHold)return;clearTimeout(pickHold.timer);if(pickHold.open){suppressPickClick=performance.now()+700;hidePreview();}pickHold=null;}
app.addEventListener('pointerdown',e=>{const card=e.target.closest('.pick-pool [data-piece]');if(!card||card.disabled||e.button!==0||modal.open)return;endPickHold();const hold={card,x:e.clientX,y:e.clientY,open:false};pickHold=hold;hold.timer=setTimeout(()=>{if(pickHold!==hold)return;hold.open=true;suppressPickClick=Infinity;showPreview(card);},450);});
window.addEventListener('pointermove',e=>{if(pickHold&&Math.hypot(e.clientX-pickHold.x,e.clientY-pickHold.y)>12)endPickHold();});
window.addEventListener('pointerup',endPickHold);window.addEventListener('pointercancel',endPickHold);window.addEventListener('blur',endPickHold);
app.addEventListener('contextmenu',e=>{if(e.target.closest('.pick-pool [data-piece]'))e.preventDefault();});
app.addEventListener('pointermove',e=>{if(pieceDrag||game.phase!=='placement'||!selected)return;const cell=e.target.closest('[data-square]');previewDeployment(selected,cell?Number(cell.dataset.square):null);});
app.addEventListener('pointerleave',()=>{if(!pieceDrag){document.querySelectorAll('.deployment-shadow,.deploy-route').forEach(el=>el.classList.contains('deployment-shadow')?el.remove():el.classList.remove('deploy-route'));}});
